require_once __DIR__ . '/../includes/config.php';
require_role(['admin','student','host','coordinator','volunteer']); $page_title='Events'; require __DIR__.'/../includes/header.php'; $events=[];if($pdo){$events=$pdo->query("SELECT * FROM events WHERE status='approved' ORDER BY event_date ASC")->fetchAll();} ?><div class="container py-5"><div class="row align-items-end mb-4"><div class="col"><div class="section-kicker">Discover</div><h1 class="fw-bold">Campus events</h1><p class="text-secondary">Find your next competition, workshop, fest or community experience.</p></div><div class="col-md-4"><input id="eventSearch" class="form-control" placeholder="Search events..."></div></div><div class="row g-4" id="eventGrid"><?php foreach($events as $ev): ?><div class="col-md-6 col-lg-4 event-item"><div class="event-card overflow-hidden"><div class="event-cover"><div class="date-pill"><small class="text-secondary d-block"><?=date('M',strtotime($ev['event_date']))?></small><strong><?=date('d',strtotime($ev['event_date']))?></strong></div></div><div class="p-4"><span class="metric-chip"><?=e($ev['category'])?></span><h4 class="mt-3"><?=e($ev['title'])?></h4><p class="small text-secondary"><?=e($ev['description'])?></p><div class="small text-secondary mb-3"><i class="bi bi-geo-alt"></i> <?=e($ev['venue'])?></div><div class="d-flex gap-2"><a class="btn btn-dark rounded-pill flex-grow-1" href="/user/event.php?id=<?=$ev['id']?>">Details</a><?php if (($user['role'] ?? '') !== 'admin'): ?><a class="btn btn-outline-primary rounded-pill" href="/user/register_event.php?id=<?=$ev['id']?>">Register</a><?php endif; ?></div></div></div></div><?php endforeach; if(!$events): ?><div class="col-12"><div class="dash-card empty">No approved events yet. Your HOD can publish the first one from the admin panel.</div></div><?php endif;?></div></div><script>document.getElementById('eventSearch')?.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.event-item').forEach(x=>x.style.display=x.innerText.toLowerCase().includes(q)?'':'none')});</script><?php require __DIR__.'/../includes/footer.php'; ?>
